    final left = parseOperand();
    _skipWs();
    if (_peek('==')) {
      pos += 2;
      return left == parseOperand();
    }
    if (_peek('!=')) {
      pos += 2;
      return left != parseOperand();
    }
    return left is bool && left; // bare boolean operand
  }

