    _skipWs();
    if (_peek("'")) {
      final end = src.indexOf("'", pos + 1);
      if (end < 0) throw FormatException('unterminated string at $pos');
      final lit = src.substring(pos + 1, end);
      pos = end + 1;
      return lit;
    }
    if (_peekWord('true')) return true;
    if (_peekWord('false')) return false;
    if (_peekWord('contains')) {
      pos += 'contains'.length;
      _skipWs();
      if (!_peek('(')) throw FormatException('expected ( after contains');
      pos++;
      final haystack = parseOperand();
      _skipWs();
      if (!_peek(',')) throw FormatException('expected , in contains()');
      pos++;
      _skipWs();
      final needle = parseOperand() as String;
      _skipWs();
      if (!_peek(')')) throw FormatException('expected ) closing contains');
      pos++;
      return haystack is String && haystack.contains(needle);
