  test('all five stubs track the SAME factory ref (teammate, SM, merge, '
      'kicker and merge-trigger in lockstep)', () {
    final refs = stubs.values
        .map((s) => pinnedRef(s.$1, s.$2))
        .toList(growable: false);
    for (var i = 1; i < refs.length; i++) {
      expect(
        refs[i],
