  bool parseOr() {
    var left = parseAnd();
    while (_peekWord('||')) {
      final right = parseAnd();
      left = left || right;
    }
    return left;
  }

  bool parseAnd() {
    var left = parseUnary();
    while (_peekWord('&&')) {
      final right = parseUnary();
      left = left && right;
    }
    return left;
