      if (!_peek(')')) throw FormatException('expected ) closing contains');
      pos++;
      return haystack is String && haystack.contains(needle);
    }
    // Dotted context path.
    final match = RegExp(r'[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z0-9_*]+)*')
        .firstMatch(src.substring(pos));
    if (match == null) {
      throw FormatException('cannot parse operand at $pos in "$src"');
    }
    pos += match.end;
    return ctxLookup(match.group(0)!);
  }

  // Mirrors GitHub semantics closely enough for these scenarios: missing
  // context paths resolve to null (`null == false` is false, `contains()`
  // on null is false) instead of throwing mid-expression.
  Object? ctxLookup(String path) {
    var node = <String, Object?>{'github': ctx['github'] as Object? ?? const {}};
    for (final part in path.split('.')) {
      if (node is Map<String, Object?> && node.containsKey(part)) {
        node = node[part] as Map<String, Object?>;
      } else {
        return null;
      }
    }
    return node;
  }

  bool _peek(String s) => src.substring(pos).trimLeft().startsWith(s);

  bool _peekWord(String w) {
    final rest = src.substring(pos).trimLeft();
    if (!rest.startsWith(w)) return false;
    return true;
  }

  void _skipWs() {
    while (pos < src.length && (src[pos] == ' ' || src[pos] == '\n')) {
      pos++;
    }
  }
}

