import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

/// Subset of GitHub Actions expressions used by the machine-merge guard:
/// parentheses, `||`, `&&`, `==`, `!=`, `contains(path, 'lit')`,
/// string/boolean literals and dotted context paths.
class GhExpr {
  final String src;
  int pos = 0;
  GhExpr(this.src);

  static bool eval(String expression, Map<String, Object?> ctx) =>
      GhExpr(expression)..parseOr().expectEnd();

  void expectEnd() {
    final rest = src.substring(pos).trim();
    if (rest.isNotEmpty) {
      throw FormatException('trailing input at ${pos}: "$rest"');
    }
  }

  bool parseOr() {
    var left = parseAnd();
    while (_peekWord('||')) {
      final right = parseAnd();
      left = left || right;
    }
    return left;
  }

  bool parseAnd() {
    var left = parseUnary();
    while (_peekWord('&&')) {
      final right = parseUnary();
      left = left && right;
    }
    return left;
  }

  bool parseUnary() {
    _skipWs();
    if (_peek('(')) {
      pos++;
      final inner = parseOr();
      _skipWs();
      if (!_peek(')')) {
        throw FormatException('expected ) at $pos in "$src"');
      }
      pos++;
      return inner;
    }
    return parseComparison();
  }

  bool parseComparison() {
    final left = parseOperand();
    _skipWs();
    if (_peek('==')) {
      pos += 2;
      return left == parseOperand();
    }
    if (_peek('!=')) {
      pos += 2;
      return left != parseOperand();
    }
    return left is bool && left; // bare boolean operand
  }

  Object? parseOperand() {
    _skipWs();
    if (_peek("'")) {
      final end = src.indexOf("'", pos + 1);
      if (end < 0) throw FormatException('unterminated string at $pos');
      final lit = src.substring(pos + 1, end);
      pos = end + 1;
      return lit;
    }
    if (_peekWord('true')) return true;
    if (_peekWord('false')) return false;
    if (_peekWord('contains')) {
      pos += 'contains'.length;
      _skipWs();
      if (!_peek('(')) throw FormatException('expected ( after contains');
      pos++;
      final haystack = parseOperand();
      _skipWs();
      if (!_peek(',')) throw FormatException('expected , in contains()');
      pos++;
      _skipWs();
      final needle = parseOperand() as String;
      _skipWs();
      if (!_peek(')')) throw FormatException('expected ) closing contains');
      pos++;
      return haystack is String && haystack.contains(needle);
    }
    // Dotted context path.
    final match = RegExp(r'[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z0-9_*]+)*')
        .firstMatch(src.substring(pos));
    if (match == null) {
      throw FormatException('cannot parse operand at $pos in "$src"');
    }
    pos += match.end;
    return ctxLookup(match.group(0)!);
  }

  // Mirrors GitHub semantics closely enough for these scenarios: missing
  // context paths resolve to null (`null == false` is false, `contains()`
  // on null is false) instead of throwing mid-expression.
  Object? ctxLookup(String path) {
    var node = <String, Object?>{'github': ctx['github'] as Object? ?? const {}};
    for (final part in path.split('.')) {
      if (node is Map<String, Object?> && node.containsKey(part)) {
        node = node[part] as Map<String, Object?>;
      } else {
        return null;
      }
    }
    return node;
  }

  bool _peek(String s) => src.substring(pos).trimLeft().startsWith(s);

  bool _peekWord(String w) {
    final rest = src.substring(pos).trimLeft();
    if (!rest.startsWith(w)) return false;
    return true;
  }

  void _skipWs() {
    while (pos < src.length && (src[pos] == ' ' || src[pos] == '\n')) {
      pos++;
    }
  }
}

