          'action': action,
          'pull_request': {
            'head': {
              'repo': {'fork': fork},
            },
          },
          'label': {'name': label},
        },
      },
    };

Map<String, Object?> namedEvent(String name) => {
      'github': {'event_name': name, 'event': const {}},
    };

